from content_16_20 import add, SHOP

add('lm16-01', ('Избираш партньор по клиентска задача.', 'Разделяш наблюдение от предположение.', 'Сравняваш принос и изпълнимост.'),
 'Съответствие: две страни помагат на една клиентска задача. Reach: достигната аудитория, не доказана покупка.',
 'Познат източник може да намали несигурността; броят последователи не доказва, че човекът търси тази услуга.',
 SHOP+' A: интериорен консултант с 12 учебни проекта и 5 въпроса за шкафове. B: създател с 80 000 последователи, без данни за нужда от мебели. C: местен доставчик с 8 подходящи разговора, но само 4 часа свободно време.',
 'Направи матрица „нужда — доказателство — общ принос — неизвестно — следващ въпрос“ за A, B и C. Избери един ограничен пилот.',
 ('Всеки извод сочи даден факт.', 'Не приписваш търсене на 80 000 последователи.', 'Избраният пилот се побира във времето.'),
 'A има най-пряко предоставено съответствие; пилотът може да отговаря на петте въпроса с пример за обхват. C е възможен само с малка задача до 4 часа. За B първо проверяваме темите и аудиторията. Няма доказана бъдеща продажба за никого.',
 'Дай на ИИ само трите реда. Отхвърли предложение „B гарантира най-много клиенти“. Поискай да посочи липсващото доказателство.')
add('lm16-02', ('Пишеш конкретно предложение.', 'Показваш ползата и за двете страни.', 'Приключваш подредено при отказ.'),
 'Пилот: ограничена проверка на обща работа. Следваща стъпка: действие, на което партньорът може да отговори.',
 'Човекът приема по-лесно разбираема задача с ограничен ангажимент, отколкото неясно обещание за голям успех.',
 SHOP+' A иска по-малко неясни запитвания. Работилницата може да даде едностраничен списък за размери. A може да го покаже при 5 подходящи консултации. Разговор за пилот: 20 минути; още няма съгласие.',
 'Напиши предложение до 120 думи с принос, обхват, срок за преглед и една следваща стъпка. Напиши и отговор на „не сега“.',
 ('Различаваш предложено от договорено.', 'Има конкретен принос от всяка страна.', 'Отказът не активира нежелана серия.'),
 '„Предлагам 30-дневен пилот: ние даваме списък за размери, Вие го предлагате при пет подходящи консултации. Отчитаме доброволните запитвания и липсващите уточнения. Удобен ли е 20-минутен разговор за обхвата?“ При отказ: „Разбирам; приключвам предложението. Благодаря за уточнението.“',
 'ИИ редактира дължината и яснотата. Ако добави „партньорството е потвърдено“, върни статуса „предложено“.')
add('lm16-03', ('Пишеш условия за пилот.', 'Ограничаваш права и данни по цел.', 'Приемаш работата по доказателство.'),
 'Обхват: какво влиза. Права: разрешена употреба. Приемане: предварително определена проверка.',
 'Ясният договор намалява риска от различни очаквания; плащането за събитие не дава автоматични права върху чужд списък.',
 'Пилот: 30 дни, общ разход €300, един списък за размери и пет консултации. Снимка е разрешена само за органичен пост за 30 дни; реклама не е разрешена. Партньорът предлага експорт на всички свои клиенти; основание и прозрачност не са предоставени.',
 'Напиши кратък term sheet: резултати, собственици, разход, срок, права, минимални данни, преглед и край. Отбележи блокираното споделяне.',
 ('Органичните права не се разширяват до реклама.', 'Не приемаш експорт без проверка на цел и основание.', 'Краят урежда активните задачи и достъпа.'),
 'Приемаме готов списък и отчет за пет консултации без клиентски лични данни. Записваме разход €300 и преглед на ден 30. Снимката остава само органична; за реклама е нужен отделен допустим обхват. Масовият експорт се спира до проверка. При край приключваме активните задачи и отнемаме излишния достъп.',
 'ИИ може да търси противоречия в условията, но не удостоверява правна допустимост. Нека маркира всяко непредоставено разрешение.', sources=('privacy',))
add('lm16-04', ('Създаваш brief с верни твърдения.', 'Обозначаваш платения контекст.', 'Отхвърляш измислен опит.'),
 'Brief: задача за създателя. Обозначение: разбираема информация за материалната връзка. Доказателство: наблюдаваното използване.',
 'Доверието изисква човекът да разбере кой плаща и какво действително е изпробвано.',
 'Създател получава €150 и продукта вчера. Има първа демонстрация; няма дългогодишна употреба или измерени резултати за всички клиенти. Платената връзка трябва да е ясна в самия материал.',
 'Напиши brief с три разрешени твърдения, видимо обозначение, забранени добавки и критерий за приемане.',
 ('Няма „ползвам от години“.', 'Платеният контекст е видим навреме.', 'Твърдението съответства на показаното.'),
 'Допустимо: „Платена демонстрация; това е първото ми използване.“ Показваме действително наблюдаваната функция. Не приемаме „всички получават същия резултат“. Приемането проверява обозначение, кадри и еднакви условия в текст и видео.',
 'ИИ предлага сценарий само от предоставените наблюдения. Не генерира фалшив клиентски отзив или биография.', sources=('creator',))
add('lm16-05', ('Разграничаваш препоръка от отзив.', 'Пишеш прозрачни условия за награда.', 'Проверяваш уникален резултат преди плащане.'),
 'Referral: препоръка към допустимо действие. Review: публично мнение; стимулът може да го направи недопустим по платформени правила.',
 'Помощта при избор не изисква купено положително мнение.',
 'Идея A: €20 за уникален нов клиент с изпълнена и платена поръчка, при ясни условия. Идея B: €20 срещу петзвезден Google отзив. Два записа сочат една поръчка P01. Връщане и самопрепоръка още нямат правила.',
 'Напиши условия за A, проверка срещу дублиране и правило за край. Обясни защо B се отхвърля.',
 ('Наградата не изисква положителен отзив.', 'P01 получава само една допустима награда.', 'Връщане и самопрепоръка имат ясна обработка.'),
 'B се отхвърля като стимулиран отзив. A може да се разглежда отделно при прозрачни условия и допустим процес. P01 се проверява веднъж след изпълнение и плащане. Правилата за връщане и самопрепоръка се уточняват преди старта; не ги добавяме след резултата.',
 'ИИ проверява дали условията скрито обвързват наградата с рейтинг. MCP може да прочете статуса на P01 само в разрешен обхват; плащането изисква валидиран резултат.', sources=('reviews','mcp'))
add('lm16-06', ('Планираш полезно събитие.', 'Смяташ цена и принос по една основа.', 'Разделяш присъствие от продажба.'),
 'Квалифициран разговор: покрива предварително зададени условия. Принос след събитието: принос от поръчките минус пълния разход.',
 'Събитието помага, ако отговаря на реален въпрос и оставя доброволна следваща стъпка.',
 'Учебно събитие за размери струва общо €600. Има 12 подходящи разговора и 3 изпълнени платени поръчки с принос €250 всяка преди събитието. Няма данни за бъдещи покупки.',
 'Напиши тема, три полезни точки, доброволна следваща стъпка и отчет с две сметки.',
 ('€600 се делят на 12 подходящи разговора.', 'Три поръчки не се удвояват по присъствие.', 'Бъдещ приход остава неизвестен.'),
 'Цена на подходящ разговор: €50. Принос от трите поръчки: €750; след събитието €150. Това не е обща нетна печалба. Тема: „Какви размери да подготвим за шкаф“. Следваща стъпка: доброволно запитване за уточняване, без обещан срок.',
 'ИИ може да подреди програмата и да провери знаменателите; не превръща присъствалите автоматично в клиенти.')
add('lm16-07', ('Разделяш споменаване, посещение и продажба.', 'Проверяваш качество и права на линк.', 'Измерваш AI видимост като наблюдение.'),
 'UTM: етикет на маршрут. AI споменаване: наблюдаван отговор за конкретна заявка. Атрибуция: правило за приписване, не доказана причина.',
 'Полезният контекст подпомага избора; платен линк не гарантира класиране или AI препоръка.',
 'Партньорски пост има 200 посещения, 8 запитвания, 3 подходящи и 1 платена поръчка. AI отговор в една проверка споменава бизнеса; в друга не. Платен линк е предложен като „гаранция за Google“.',
 'Направи отчет за периода с маршрут, уникални резултати и неизвестно. Напиши решение за платения линк.',
 ('Не приемаш гаранция за класиране.', 'Периодът и дефинициите са явни.', 'Две AI проверки не доказват обща видимост.'),
 'Отчитаме 200 посещения → 8 заявки → 3 подходящи → 1 поръчка за дадения период. Проверяваме други допустими сигнали и качеството на заявките. Отхвърляме гаранцията; AI проверката се пази с дата, заявка и източник. Причинният принос на линка е неизвестен.',
 'ИИ обобщава отчета, но трябва да запази периода и несигурността. MCP може да прочете разрешения отчет; написаното резюме не е измерване.')
add('lm16-08', ('Избираш пилот по качество и икономика.', 'Разпределяш бюджет с резерв.', 'Пишеш условия за продължаване и стоп.'),
 'Пилотът е ограничен тест; историческият принос не е прогнозна гаранция.',
 'Партньор, който обещава невъзможни срокове, увеличава несигурността дори при евтин контакт.',
 '90 дни, бюджет €900, време за две инициативи. A: разход €300, 15 подходящи разговора, 3 клиента. B: €200, 20 разговора, 1 клиент и повторени невъзможни обещания. C: €400, 8 разговора, 4 клиента. Учебен принос преди пилота €250 на клиент; всички разходи за пилота са включени.',
 'Направи 90-дневен план с две инициативи, целия бюджет, прегледи на дни 30/60/90 и незабавно правило за поправка при неверни обещания.',
 ('Сметката включва пълния разход.', 'Не мащабираш B само по цена на разговор.', 'Има резерв и отговорник за активните клиенти.'),
 'A: 3×250−300=€450; B: €50; C: €600 след пилотните разходи. Избираме ограничени A и C за €700, резерв €200. Проверяваме качество и капацитет на дни 30/60/90. B се коригира и спира при повторение; €10 на разговор не оправдават неверен срок. Историческите числа не гарантират повторение.',
 'ИИ сравнява два допустими плана и посочва факт за всяко решение. Разрешен MCP отчет може да се прочете; договор, плащане или публикация се правят само в предварително разрешен обхват.')
